'use strict';
let inlineTextEdit=null;
document.body.insertAdjacentHTML('beforeend','<section id="inlineTextEditor" hidden aria-label="Edit text on canvas"><div class="inline-text-heading"><strong>Edit text</strong><button id="commitInlineText">Done</button><button id="cancelInlineText">Cancel</button></div><textarea id="inlineTextValue" maxlength="10000" rows="3" aria-label="Editable canvas text" spellcheck="true"></textarea><p>Enter: new line · Ctrl+Enter: save · Esc: cancel</p></section>');
function placeInlineText(){if(!inlineTextEdit)return;const o=inlineTextEdit.actor,r=$('stage').getBoundingClientRect(),v=stateAt(o,time),camera=cameraAt(current(),time),p={x:r.left+((v.x-camera.x)*camera.zoom+480)*r.width/960,y:r.top+((v.y-camera.y)*camera.zoom+270)*r.height/540},editor=$('inlineTextEditor'),width=Math.min(440,innerWidth-24),height=Math.min(250,innerHeight-24);editor.style.width=width+'px';editor.style.left=clamp(p.x-width/2,12,innerWidth-width-12)+'px';editor.style.top=clamp(p.y-80,12,innerHeight-height-12)+'px';const input=$('inlineTextValue'),appearance=capturedTextStyle(o);input.style.fontFamily=appearance.textFont==='mono'?'Consolas, monospace':appearance.textFont==='serif'?'Georgia, serif':'Arial, sans-serif';input.style.fontWeight=appearance.textWeight;input.style.fontStyle=appearance.textStyle.italic?'italic':'normal';input.style.textAlign=appearance.textStyle.align}
function beginInlineText(o=object()){if(recording||playing||motionTake||!o||o.type!=='text'||o.locked)return toast('Select an unlocked text layer to edit.');if(inlineTextEdit)finishInlineText();stop();selectLayers([o.id]);inlineTextEdit={project,sceneId:current().id,actor:o,text:o.text||'',name:o.name,richText:structuredClone(o.richText),wordAnimation:structuredClone(o.wordAnimation)};window.editorTaskBusy=true;$('inlineTextEditor').hidden=false;$('inlineTextValue').value=o.text||'';placeInlineText();$('inlineTextValue').focus();$('inlineTextValue').select()}
function finishInlineText(cancel=false,renderAfter=true){const edit=inlineTextEdit;if(!edit)return;inlineTextEdit=null;$('inlineTextEditor').hidden=true;window.editorTaskBusy=false;if(project!==edit.project||current().id!==edit.sceneId||!current().objects.includes(edit.actor))return;if(cancel||edit.actor.locked){edit.actor.text=edit.text;edit.actor.name=edit.name;edit.actor.richText=edit.richText;edit.actor.wordAnimation=edit.wordAnimation}else{edit.actor.text=$('inlineTextValue').value;edit.actor.name=edit.actor.text.slice(0,80)||'Text';save()}if(renderAfter)render();else{draw();renderTimeline();if($('textValue'))$('textValue').value=edit.actor.text}}
$('inlineTextValue').oninput=e=>{if(!inlineTextEdit)return;if(typeof reconcileTextMetadata==='function')reconcileTextMetadata(inlineTextEdit.actor,inlineTextEdit.actor.text||'',e.target.value);inlineTextEdit.actor.text=e.target.value;inlineTextEdit.actor.name=e.target.value.slice(0,80)||'Text';draw()};$('commitInlineText').onclick=()=>finishInlineText();$('cancelInlineText').onclick=()=>finishInlineText(true);
$('inlineTextValue').addEventListener('keydown',e=>{e.stopPropagation();if(e.key==='Escape'){e.preventDefault();finishInlineText(true)}else if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();finishInlineText()}});
document.addEventListener('pointerdown',e=>{if(inlineTextEdit&&!$('inlineTextEditor').contains(e.target)&&!e.target.closest('.rich-range-tools')){finishInlineText(false,false)}},true);
$('stage').addEventListener('dblclick',e=>{if(recording||motionTake||canvasMode!=='select')return;const p=pointerWorld(e,null),top=current().objects.slice().reverse().find(o=>hitLayer(o,p));if(top?.type==='text'){e.preventDefault();beginInlineText(top)}});
const addTextBeforeInline=$('addText').onclick;$('addText').textContent='＋ Editable text';$('addText').title='Add a text layer. Double-click it on the canvas to edit.';$('addText').onclick=()=>{if(recording||motionTake)return;addTextBeforeInline();const o=object();if(o?.type==='text'){o.keys[0].v.x=480;o.keys[0].v.y=270;o.textFont='sans';save();render()}};
const controlsBeforeInlineText=renderControls;renderControls=function(){controlsBeforeInlineText();if(object()?.type!=='text')return;const b=storyButton('Edit wording on canvas',()=>beginInlineText());b.id='editTextOnCanvas';b.disabled=!!object().locked;$('controls').prepend(b)};
window.addEventListener('resize',placeInlineText);const loadBeforeInlineText=loadProject;loadProject=function(p){if(inlineTextEdit)finishInlineText(true);return loadBeforeInlineText(p)};const historyBeforeInlineText=restoreHistory;restoreHistory=function(snap){if(inlineTextEdit)finishInlineText(true);return historyBeforeInlineText(snap)};
